const PptxGenJS = require('pptxgenjs');
const path = require('path');

const outDir = process.env.SKILL_SANDBOX_OUT_DIR || '/workspace/output';
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 in

const FONT_CN = '微软雅黑';
const COLOR_TITLE = '1F3864';
const COLOR_BODY = '2D2D2D';
const COLOR_ACCENT = 'C0504D';

function addFooter(slide, pageNum) {
  slide.addText(`Project Morning Star / 晨星项目   ${pageNum}/3`, {
    x: 0.5, y: 7.0, w: 12.33, h: 0.3,
    fontSize: 10, color: '666666', align: 'right'
  });
}

// Slide 1: Objectives / 目标
const s1 = pres.addSlide();
s1.addText('Objectives / 目标', {
  x: 0.7, y: 0.5, w: 12, h: 0.9,
  fontSize: 36, bold: true, color: COLOR_TITLE, fontFace: FONT_CN
});
s1.addShape(pres.ShapeType.rect, { x: 0.7, y: 1.45, w: 2.0, h: 0.06, fill: { color: COLOR_ACCENT } });

s1.addText([
  { text: '验证合成项目“晨星”的技术可行性与演示能力\n', options: { fontSize: 22, bold: true, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: 'Validate technical feasibility and demonstration capability of Synthetic Project Morning Star\n\n', options: { fontSize: 18, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '• 完成概念验证（PoC）级别的测试演示\n', options: { fontSize: 20, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '  Deliver a proof-of-concept (PoC) level test demonstration\n\n', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '• 收集实验数据，评估后续迭代方向\n', options: { fontSize: 20, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '  Collect experimental data to guide next iteration\n\n', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '⚠ 预算与交付日期尚未确定 / Budget & delivery date TBD', options: { fontSize: 18, bold: true, color: COLOR_ACCENT, fontFace: FONT_CN } }
], { x: 0.7, y: 1.8, w: 11.5, h: 4.8, valign: 'top', lineSpacingMultiple: 1.15 });

addFooter(s1, 1);

// Slide 2: Experimental Results / 实验结果
const s2 = pres.addSlide();
s2.addText('Experimental Results / 实验结果', {
  x: 0.7, y: 0.5, w: 12, h: 0.9,
  fontSize: 36, bold: true, color: COLOR_TITLE, fontFace: FONT_CN
});
s2.addShape(pres.ShapeType.rect, { x: 0.7, y: 1.45, w: 2.0, h: 0.06, fill: { color: COLOR_ACCENT } });

// Summary callout
s2.addShape(pres.ShapeType.roundRect, {
  x: 0.7, y: 1.8, w: 11.9, h: 1.2,
  fill: { color: 'FFF3CD' }, rectRadius: 0.15,
  line: { color: 'E0A800', width: 1.5 }
});
s2.addText([
  { text: '⚠ 3次实验中2次通过、1次待复核，并非全部成功\n', options: { fontSize: 20, bold: true, color: '856404', fontFace: FONT_CN, breakLine: true } },
  { text: '2 of 3 experiments passed; 1 awaiting review — NOT all successful', options: { fontSize: 16, italic: true, color: '856404', fontFace: FONT_CN } }
], { x: 1.0, y: 1.9, w: 11.3, h: 1.0, valign: 'middle' });

// Table
const tableRows = [
  [
    { text: '#', options: { bold: true, color: 'FFFFFF', fill: { color: COLOR_TITLE }, fontSize: 16, fontFace: FONT_CN, align: 'center' } },
    { text: '实验 / Experiment', options: { bold: true, color: 'FFFFFF', fill: { color: COLOR_TITLE }, fontSize: 16, fontFace: FONT_CN } },
    { text: '状态 / Status', options: { bold: true, color: 'FFFFFF', fill: { color: COLOR_TITLE }, fontSize: 16, fontFace: FONT_CN } },
    { text: '备注 / Notes', options: { bold: true, color: 'FFFFFF', fill: { color: COLOR_TITLE }, fontSize: 16, fontFace: FONT_CN } }
  ],
  [
    { text: '1', options: { fontSize: 16, fontFace: FONT_CN, align: 'center' } },
    { text: '实验一 / Exp #1', options: { fontSize: 16, fontFace: FONT_CN } },
    { text: '✅ 通过 / Passed', options: { fontSize: 16, fontFace: FONT_CN, color: '28A745' } },
    { text: '符合预期 / Met expectations', options: { fontSize: 14, fontFace: FONT_CN, color: '555555' } }
  ],
  [
    { text: '2', options: { fontSize: 16, fontFace: FONT_CN, align: 'center' } },
    { text: '实验二 / Exp #2', options: { fontSize: 16, fontFace: FONT_CN } },
    { text: '✅ 通过 / Passed', options: { fontSize: 16, fontFace: FONT_CN, color: '28A745' } },
    { text: '符合预期 / Met expectations', options: { fontSize: 14, fontFace: FONT_CN, color: '555555' } }
  ],
  [
    { text: '3', options: { fontSize: 16, fontFace: FONT_CN, align: 'center' } },
    { text: '实验三 / Exp #3', options: { fontSize: 16, fontFace: FONT_CN } },
    { text: '⏳ 待复核 / Awaiting Review', options: { fontSize: 16, fontFace: FONT_CN, color: 'D39E00' } },
    { text: '需进一步确认 / Pending confirmation', options: { fontSize: 14, fontFace: FONT_CN, color: '555555' } }
  ]
];

s2.addTable(tableRows, {
  x: 0.7, y: 3.3, w: 11.9,
  colW: [0.6, 3.5, 3.8, 4.0],
  rowH: [0.55, 0.55, 0.55, 0.55],
  border: { type: 'solid', pt: 0.5, color: 'CCCCCC' },
  autoPage: false
});

addFooter(s2, 2);

// Slide 3: Next Steps / 下一步
const s3 = pres.addSlide();
s3.addText('Next Steps / 下一步', {
  x: 0.7, y: 0.5, w: 12, h: 0.9,
  fontSize: 36, bold: true, color: COLOR_TITLE, fontFace: FONT_CN
});
s3.addShape(pres.ShapeType.rect, { x: 0.7, y: 1.45, w: 2.0, h: 0.06, fill: { color: COLOR_ACCENT } });

s3.addText([
  { text: '1. 完成实验三复核，确认最终结果\n', options: { fontSize: 22, bold: true, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '   Complete review of Experiment #3 and confirm final results\n\n', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '2. 汇总三次实验数据，形成分析报告\n', options: { fontSize: 22, bold: true, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '   Consolidate data from all 3 experiments into an analysis report\n\n', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '3. 明确预算与交付时间表\n', options: { fontSize: 22, bold: true, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '   Define budget and delivery timeline (currently TBD)\n\n', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN, breakLine: true } },
  { text: '4. 根据复核结论决定是否进入下一阶段\n', options: { fontSize: 22, bold: true, color: COLOR_BODY, fontFace: FONT_CN, breakLine: true } },
  { text: '   Decide whether to proceed to next phase based on review outcome', options: { fontSize: 16, italic: true, color: '555555', fontFace: FONT_CN } }
], { x: 0.7, y: 1.8, w: 11.5, h: 5.0, valign: 'top', lineSpacingMultiple: 1.1 });

addFooter(s3, 3);

pres.writeFile({ fileName: path.join(outDir, 'slides.pptx') })
  .then(() => console.log('PPTX created: ' + path.join(outDir, 'slides.pptx')))
  .catch(err => { console.error(err); process.exit(1); });

const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');
const path = require('path');

const outDir = process.env.SKILL_SANDBOX_OUT_DIR || '/workspace/output';
const cjkFontPath = process.env.SKILL_SANDBOX_CJK_FONT || '/usr/share/fonts/workspacex/NotoSansSC-Common.otf';

const PAGE_W = 960; // landscape wide (points) ~13.33in
const PAGE_H = 540; // landscape tall (points) ~7.5in
const MARGIN_L = 50;
const MARGIN_R = 50;
const CONTENT_W = PAGE_W - MARGIN_L - MARGIN_R;

const COLOR_TITLE = [0.12, 0.22, 0.39]; // #1F3864
const COLOR_BODY = [0.18, 0.18, 0.18];
const COLOR_ACCENT = [0.75, 0.31, 0.30]; // #C0504D
const COLOR_WARN_BG = [1.0, 0.95, 0.80]; // #FFF3CD
const COLOR_WARN_BORDER = [0.88, 0.66, 0.0];
const COLOR_WARN_TEXT = [0.52, 0.39, 0.02];
const COLOR_GREEN = [0.16, 0.65, 0.27];
const COLOR_AMBER = [0.83, 0.62, 0.0];
const COLOR_GRAY = [0.4, 0.4, 0.4];
const COLOR_WHITE = [1, 1, 1];
const COLOR_HEADER_BG = [0.12, 0.22, 0.39];

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync(cjkFontPath);
  const font = await doc.embedFont(fontBytes);

  function addFooter(page, num) {
    page.drawText(`Project Morning Star / 晨星项目   ${num}/3`, {
      x: PAGE_W - MARGIN_R, y: 20, size: 9, font, color: COLOR_GRAY, textAlign: 'right'
    });
  }

  function drawRect(page, x, y, w, h, color) {
    page.drawRectangle({ x, y, width: w, height: h, color });
  }

  function drawRoundedRect(page, x, y, w, h, borderColor, bgColor) {
    page.drawRectangle({ x, y, width: w, height: h, color: bgColor, borderColor, borderWidth: 1.5 });
  }

  // ===== SLIDE 1: Objectives =====
  const p1 = doc.addPage([PAGE_W, PAGE_H]);
  p1.drawText('Objectives / 目标', { x: MARGIN_L, y: PAGE_H - 60, size: 30, font, color: COLOR_TITLE });
  drawRect(p1, MARGIN_L, PAGE_H - 72, 150, 4, COLOR_ACCENT);

  const s1Lines = [
    { t: '验证合成项目"晨星"的技术可行性与演示能力', s: 18, c: COLOR_BODY, bold: true },
    { t: 'Validate technical feasibility and demonstration capability of Synthetic Project Morning Star', s: 13, c: COLOR_GRAY },
    { t: '', s: 8, c: COLOR_BODY },
    { t: '• 完成概念验证（PoC）级别的测试演示', s: 16, c: COLOR_BODY },
    { t: '  Deliver a proof-of-concept (PoC) level test demonstration', s: 12, c: COLOR_GRAY },
    { t: '', s: 8, c: COLOR_BODY },
    { t: '• 收集实验数据，评估后续迭代方向', s: 16, c: COLOR_BODY },
    { t: '  Collect experimental data to guide next iteration', s: 12, c: COLOR_GRAY },
    { t: '', s: 12, c: COLOR_BODY },
    { t: '⚠ 预算与交付日期尚未确定 / Budget & delivery date TBD', s: 15, c: COLOR_ACCENT }
  ];
  let yPos = PAGE_H - 105;
  for (const line of s1Lines) {
    p1.drawText(line.t, { x: MARGIN_L + 10, y: yPos, size: line.s, font, color: line.c });
    yPos -= (line.s + 8);
  }
  addFooter(p1, 1);

  // ===== SLIDE 2: Experimental Results =====
  const p2 = doc.addPage([PAGE_W, PAGE_H]);
  p2.drawText('Experimental Results / 实验结果', { x: MARGIN_L, y: PAGE_H - 60, size: 30, font, color: COLOR_TITLE });
  drawRect(p2, MARGIN_L, PAGE_H - 72, 150, 4, COLOR_ACCENT);

  // Warning box
  const warnY = PAGE_H - 170;
  drawRoundedRect(p2, MARGIN_L, warnY, CONTENT_W, 70, COLOR_WARN_BORDER, COLOR_WARN_BG);
  p2.drawText('⚠ 3次实验中2次通过、1次待复核，并非全部成功', {
    x: MARGIN_L + 15, y: warnY + 42, size: 16, font, color: COLOR_WARN_TEXT
  });
  p2.drawText('2 of 3 experiments passed; 1 awaiting review — NOT all successful', {
    x: MARGIN_L + 15, y: warnY + 18, size: 12, font, color: COLOR_WARN_TEXT
  });

  // Table header
  const tblX = MARGIN_L;
  const tblY = warnY - 30;
  const colW = [40, 260, 280, 280];
  const rowH = 36;

  // Header row
  drawRect(p2, tblX, tblY - rowH, CONTENT_W, rowH, COLOR_HEADER_BG);
  const headers = ['#', '实验 / Experiment', '状态 / Status', '备注 / Notes'];
  let hx = tblX;
  for (let i = 0; i < headers.length; i++) {
    p2.drawText(headers[i], { x: hx + 8, y: tblY - rowH + 10, size: 13, font, color: COLOR_WHITE });
    hx += colW[i];
  }

  // Data rows
  const rows = [
    ['1', '实验一 / Exp #1', '✅ 通过 / Passed', '符合预期 / Met expectations'],
    ['2', '实验二 / Exp #2', '✅ 通过 / Passed', '符合预期 / Met expectations'],
    ['3', '实验三 / Exp #3', '⏳ 待复核 / Awaiting Review', '需进一步确认 / Pending confirmation']
  ];
  const statusColors = [COLOR_GREEN, COLOR_GREEN, COLOR_AMBER];

  for (let r = 0; r < rows.length; r++) {
    const ry = tblY - rowH * (r + 2);
    // Alternating bg
    if (r % 2 === 1) {
      drawRect(p2, tblX, ry, CONTENT_W, rowH, [0.95, 0.95, 0.95]);
    }
    // Border line
    p2.drawLine({ start: { x: tblX, y: ry }, end: { x: tblX + CONTENT_W, y: ry }, thickness: 0.5, color: [0.8, 0.8, 0.8] });

    let cx = tblX;
    for (let c = 0; c < rows[r].length; c++) {
      const txtColor = c === 2 ? statusColors[r] : (c === 3 ? COLOR_GRAY : COLOR_BODY);
      p2.drawText(rows[r][c], { x: cx + 8, y: ry + 10, size: 12, font, color: txtColor });
      cx += colW[c];
    }
  }
  // Bottom border
  const bottomY = tblY - rowH * (rows.length + 1);
  p2.drawLine({ start: { x: tblX, y: bottomY }, end: { x: tblX + CONTENT_W, y: bottomY }, thickness: 0.5, color: [0.8, 0.8, 0.8] });

  addFooter(p2, 2);

  // ===== SLIDE 3: Next Steps =====
  const p3 = doc.addPage([PAGE_W, PAGE_H]);
  p3.drawText('Next Steps / 下一步', { x: MARGIN_L, y: PAGE_H - 60, size: 30, font, color: COLOR_TITLE });
  drawRect(p3, MARGIN_L, PAGE_H - 72, 150, 4, COLOR_ACCENT);

  const s3Lines = [
    { t: '1. 完成实验三复核，确认最终结果', s: 18, c: COLOR_BODY },
    { t: '   Complete review of Experiment #3 and confirm final results', s: 12, c: COLOR_GRAY },
    { t: '', s: 10, c: COLOR_BODY },
    { t: '2. 汇总三次实验数据，形成分析报告', s: 18, c: COLOR_BODY },
    { t: '   Consolidate data from all 3 experiments into an analysis report', s: 12, c: COLOR_GRAY },
    { t: '', s: 10, c: COLOR_BODY },
    { t: '3. 明确预算与交付时间表', s: 18, c: COLOR_BODY },
    { t: '   Define budget and delivery timeline (currently TBD)', s: 12, c: COLOR_GRAY },
    { t: '', s: 10, c: COLOR_BODY },
    { t: '4. 根据复核结论决定是否进入下一阶段', s: 18, c: COLOR_BODY },
    { t: '   Decide whether to proceed to next phase based on review outcome', s: 12, c: COLOR_GRAY }
  ];
  yPos = PAGE_H - 105;
  for (const line of s3Lines) {
    p3.drawText(line.t, { x: MARGIN_L + 10, y: yPos, size: line.s, font, color: line.c });
    yPos -= (line.s + 6);
  }
  addFooter(p3, 3);

  const pdfBytes = await doc.save();
  const pdfPath = path.join(outDir, 'slides.pdf');
  fs.writeFileSync(pdfPath, pdfBytes);
  console.log('PDF created: ' + pdfPath);
})().catch(err => { console.error(err.stack); process.exit(1); });

